from PIL import Image
for tag in ['initial','approach1','press3']:
 for cam in ['front','left','right','topview']:
  path=f'/app/output/initial/{cam}.png' if tag=='initial' else f'/app/output/{tag}_{cam}.png'
  im=Image.open(path)
  if cam=='front': box=(145,90,205,150)
  elif cam in ('left','right'): box=(130,85,190,145)
  else: box=(115,65,180,110)
  im.crop(box).resize(((box[2]-box[0])*6,(box[3]-box[1])*6)).save(f'/app/output/{tag}_{cam}_crop.png')
